// Illustration scenes for blog and page images. Each scene is HTML/CSS rendered at 1200×630 by make-images.cjs.
const LOGO = '<svg viewBox="0 0 32 32"><rect width="32" height="32" rx="8" fill="#141414"/><path d="M11 7h13v4h-9v3.6h7v4h-7V25h-4z" fill="#E8DCC4"/><path d="M4.5 15.6h3.8M5.8 19.6h2.5" stroke="#E8DCC4" stroke-width="2" stroke-linecap="round"/><rect x="20.5" y="20.5" width="5" height="5" rx="1.2" fill="#C8A97E"/></svg>';
const LOGO_DARK = LOGO.replace('fill="#141414"', 'fill="#E8DCC4"').replace('fill="#E8DCC4"/><path d="M4.5', 'fill="#141414"/><path d="M4.5').replace('stroke="#E8DCC4"', 'stroke="#141414"');

const BASE = `*{box-sizing:border-box;margin:0;padding:0}body{width:1200px;height:630px;overflow:hidden;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;color:#141414}
.f{position:relative;width:1200px;height:630px;display:flex;align-items:center;justify-content:center;gap:44px;padding:90px 70px 60px}
.f.dark{color:#F5EFE4}
.tag{position:absolute;left:44px;top:34px;display:flex;align-items:center;gap:10px;font-weight:800;font-size:19px;letter-spacing:-.02em}
.tag svg{width:28px;height:28px}.tag em{font-style:normal;color:#8A6D3B}.dark .tag em{color:#E8DCC4}
.lbl{position:absolute;right:44px;top:40px;font:700 14px/1 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.1em;text-transform:uppercase;color:#8A6D3B;background:rgba(255,255,255,.6);padding:8px 12px;border-radius:99px}
.dark .lbl{color:#E8DCC4;background:rgba(255,255,255,.08)}
.card{background:#fff;border-radius:22px;box-shadow:0 1px 2px rgba(20,20,20,.05),0 14px 34px rgba(20,20,20,.09);padding:26px}
.photo{position:relative;overflow:hidden;background:radial-gradient(circle at 70% 36%,#fff3c4 0 7%,transparent 7.4%),radial-gradient(120% 60% at 18% 102%,#3b3a2a 0 60%,transparent 61%),radial-gradient(120% 70% at 88% 108%,#5a4a32 0 60%,transparent 61%),linear-gradient(#f9d8a8,#ee9a64 55%,#b8573f)}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.cap{font-size:14px;font-weight:800;color:#6B6358;text-transform:uppercase;letter-spacing:.08em}
.dark .cap{color:#CFC6B6}
.col{display:flex;flex-direction:column;gap:14px}.row{display:flex;gap:16px;align-items:center}
.pill{display:inline-block;padding:7px 14px;border-radius:99px;font-weight:800;font-size:16px}
.ok{background:#E6F2E8;color:#1E5A2E}.bad{background:#FBE7E5;color:#8C1D17}
.code{background:#141414;color:#EDE4D3;border-radius:18px;padding:24px;font:500 15px/1.6 ui-monospace,Menlo,Consolas,monospace;white-space:pre}
.ph{background:#E8DCC4;border-radius:8px}
`;

const frame = (label, inner, o = {}) => `<!doctype html><html><head><meta charset="utf-8"><style>${BASE}${o.css || ''}</style></head><body>
<div class="f${o.dark ? ' dark' : ''}" style="background:${o.bg || (o.dark ? '#141414' : '#F3ECDF')};${o.style || ''}"><div class="tag">${o.dark ? LOGO_DARK : LOGO}<span>TheFast<em>Designs</em></span></div>${label ? `<div class="lbl">${label}</div>` : ''}${inner}</div>${o.script ? `<script>${o.script}</script>` : ''}</body></html>`;

const mix = (a, b, p) => { const h = x => [1, 3, 5].map(i => parseInt(x.slice(i, i + 2), 16)); const A = h(a), B = h(b); return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * p).toString(16).padStart(2, '0')).join(''); };
const sw = (c, w, h, txt = '', r = 14, fg = '#141414') => `<div style="width:${w}px;height:${h}px;background:${c};border-radius:${r}px;display:flex;align-items:flex-end;padding:10px 12px;font:700 14px ui-monospace,Menlo,monospace;color:${fg}">${txt}</div>`;
const lines = (n, w = [100, 92, 96, 70], c = '#E8DCC4', h = 12) => Array.from({ length: n }, (_, i) => `<div style="height:${h}px;width:${w[i % w.length]}%;background:${c};border-radius:6px"></div>`).join('');
const phone = (inner, o = {}) => `<div style="width:${o.w || 230}px;height:${o.h || 460}px;border-radius:36px;background:#141414;padding:10px;box-shadow:0 20px 40px rgba(0,0,0,.18)"><div style="width:100%;height:100%;border-radius:28px;overflow:hidden;background:${o.bg || '#FAF7F2'};position:relative">${inner}</div></div>`;

const S = {};

// ---------- color ----------
S['hex-rgb-hsl-cmyk-color-codes-explained'] = { alt: 'One beige color written as HEX, RGB, HSL and CMYK color codes', html: frame('Color codes', `<div class="card row" style="gap:40px;padding:34px"><div style="width:250px;height:320px;border-radius:18px;background:#C8A97E"></div><div class="col" style="gap:22px">${[['HEX', '#C8A97E'], ['RGB', 'rgb(200 169 126)'], ['HSL', 'hsl(35 40% 64%)'], ['CMYK', '0 16 37 22']].map(([k, v]) => `<div class="row" style="gap:20px"><span class="cap" style="width:70px">${k}</span><span class="mono" style="font-size:32px;font-weight:700">${v}</span></div>`).join('')}</div></div>`) };
S['how-to-build-a-color-palette-with-color-theory'] = { alt: 'Color wheel with an analogous color palette chosen using color theory', html: frame('Color theory', `<div style="width:340px;height:340px;border-radius:50%;background:conic-gradient(from 90deg,#e63946,#f4a261,#e9c46a,#8ab17d,#2a9d8f,#457b9d,#6d597a,#b5446e,#e63946);display:grid;place-items:center;box-shadow:0 14px 34px rgba(0,0,0,.12)"><div style="width:130px;height:130px;border-radius:50%;background:#F3ECDF;display:grid;place-items:center;font-weight:800;font-size:20px">60·30·10</div></div><div class="col" style="gap:12px">${[['#E07A3F', 'Primary'], ['#E9A23B', 'Accent'], ['#E9C46A', 'Highlight'], ['#3B2F2A', 'Text'], ['#FAF3E6', 'Background']].map(([c, n]) => `<div class="row" style="gap:16px">${sw(c, 300, 60, c, 14, c === '#3B2F2A' ? '#fff' : '#141414')}<span class="cap">${n}</span></div>`).join('')}</div>`) };
S['wcag-color-contrast-guide'] = { alt: 'WCAG color contrast ratio examples with passing and failing text colors', html: frame('WCAG contrast', `${[['#FAF7F2', '#3A3631', '11.1:1', 'AA ✓ AAA ✓', 'ok'], ['#FFFFFF', '#C9C2B5', '1.8:1', 'Fails AA', 'bad']].map(([bg, fg, r, t, k]) => `<div class="card col" style="background:${bg};width:440px;height:400px;justify-content:space-between;padding:34px"><div style="font-size:120px;font-weight:800;color:${fg};line-height:1">Aa</div><div style="color:${fg};font-size:22px;font-weight:600;line-height:1.4">Readable body text needs strong contrast.</div><div class="row"><span style="font-size:40px;font-weight:800">${r}</span><span class="pill ${k}">${t}</span></div></div>`).join('')}`) };
S['tints-shades-and-tones-explained'] = { alt: 'Tints and shades of one brown brand color from light to dark', html: frame('Tints & shades', `<div class="col" style="gap:18px;width:100%"><div class="row" style="gap:8px">${[.9, .75, .6, .45, .3, .15].map(p => sw(mix('#8A6D3B', '#ffffff', p), 150, 150, Math.round(p * 100) + '%', 16)).join('')}</div><div class="row" style="gap:8px">${[0, .15, .3, .45, .6, .75].map(p => sw(mix('#8A6D3B', '#000000', p), 150, 150, p ? Math.round(p * 100) + '%' : 'Base', 16, '#fff')).join('')}</div><div class="row" style="gap:40px;margin-top:4px"><span class="cap">↑ Tints · mixed with white</span><span class="cap">↓ Shades · mixed with black</span></div></div>`) };
S['how-to-pick-exact-colors-from-images'] = { alt: 'Eyedropper loupe picking an exact HEX color from a sunset photo', html: frame('Image color picker', `<div class="photo" style="width:700px;height:430px;border-radius:22px;box-shadow:0 14px 34px rgba(0,0,0,.15)"><div style="position:absolute;left:300px;top:150px;width:150px;height:150px;border-radius:50%;border:6px solid #fff;box-shadow:0 8px 24px rgba(0,0,0,.3);background:#EE9A64;display:grid;place-items:center"><div style="width:14px;height:14px;border:2px solid #fff"></div></div><div style="position:absolute;left:460px;top:200px;background:#141414;color:#fff;padding:12px 18px;border-radius:12px;font:700 24px ui-monospace,Menlo,monospace">#EE9A64</div></div>`) };
S['extract-color-palette-from-photos'] = { alt: 'Color palette of five dominant colors extracted from a landscape photo', html: frame('Palette extractor', `<div class="photo" style="width:560px;height:400px;border-radius:22px;box-shadow:0 14px 34px rgba(0,0,0,.15)"></div><div class="col" style="gap:10px">${['#F9D8A8', '#EE9A64', '#B8573F', '#5A4A32', '#3B3A2A'].map((c, i) => sw(c, 280, 66, c, 14, i > 2 ? '#fff' : '#141414')).join('')}</div>`) };
const bars = `<div class="row" style="align-items:flex-end;gap:18px;height:220px">${[[150, '#D64545'], [200, '#3FA34D'], [120, '#D64545'], [180, '#3FA34D'], [90, '#D64545'], [160, '#3FA34D']].map(([h, c]) => `<div style="width:42px;height:${h}px;background:${c};border-radius:8px 8px 0 0"></div>`).join('')}</div><div class="row" style="gap:20px;margin-top:16px"><span class="row" style="gap:8px"><i style="width:18px;height:18px;background:#D64545;border-radius:4px"></i>Loss</span><span class="row" style="gap:8px"><i style="width:18px;height:18px;background:#3FA34D;border-radius:4px"></i>Profit</span></div>`;
S['designing-for-color-blindness'] = { alt: 'Red and green bar chart shown with normal vision and simulated deuteranopia color blindness', html: frame('Color blindness', `<svg width="0" height="0" style="position:absolute"><filter id="d" color-interpolation-filters="sRGB"><feColorMatrix values="0.625 0.375 0 0 0 0.7 0.3 0 0 0 0 0.3 0.7 0 0 0 0 0 1 0"/></filter></svg>${['Normal vision', 'Deuteranopia'].map((t, i) => `<div class="card" style="width:440px;padding:30px"><div class="cap" style="margin-bottom:20px">${t}</div><div style="${i ? 'filter:url(#d)' : ''};font-weight:700">${bars}</div></div>`).join('')}`) };
const circ = (c, x) => `<div style="position:absolute;left:${x}px;top:0;width:150px;height:150px;border-radius:50%;background:${c};mix-blend-mode:multiply"></div>`;
S['digital-color-mixing-rgb-vs-paint'] = { alt: 'Blue and yellow mixed digitally to grey compared with paint mixing to green', html: frame('Color mixing', `<div class="col" style="gap:30px">${[['Screen (RGB average)', '#808080', '#808080'], ['Paint (subtractive)', '#4C9A3C', 'green']].map(([t, r, n]) => `<div class="card row" style="gap:24px;padding:24px 34px">${sw('#0000FF', 120, 120, '', 60)}<b style="font-size:40px">+</b>${sw('#FFFF00', 120, 120, '', 60)}<b style="font-size:40px">=</b>${sw(r, 120, 120, '', r === '#808080' ? 16 : 60)}<div class="col" style="gap:6px;width:250px"><span class="cap">${t}</span><b style="font-size:26px">${n === 'green' ? 'Green' : 'Grey #808080'}</b></div></div>`).join('')}</div>`) };
S['why-random-colors-look-bad-and-how-to-fix-it'] = { alt: 'Muddy random RGB colors compared with constrained pastel colors from HSL', html: frame('Random colors', ['Random RGB', 'Constrained HSL pastels'].map((t, i) => `<div class="card" style="width:460px"><div class="cap" style="margin-bottom:16px">${t}</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px">${(i ? ['#F4C2C2', '#C9E4DE', '#FDE2B6', '#C6DEF1', '#DBCDF0', '#F2C6DE', '#FAEDCB', '#C9E4C5', '#F7D9C4', '#BFD7EA', '#E2CFEA', '#D3EFC8'] : ['#7A6B52', '#5E6D74', '#8C7F6A', '#6B5A6E', '#4F5D45', '#8A7B7E', '#6E6A3F', '#5A6E6B', '#7D5F4C', '#696A7C', '#836E5B', '#5C5550']).map(c => `<div style="height:84px;border-radius:12px;background:${c}"></div>`).join('')}</div></div>`).join('')) };
S['css-color-names-history-and-color-matching'] = { alt: 'CSS named colors including rebeccapurple, tomato, steelblue and papayawhip', html: frame('CSS color names', `<div style="display:grid;grid-template-columns:repeat(4,240px);gap:14px">${[['rebeccapurple', '#663399'], ['tomato', '#FF6347'], ['steelblue', '#4682B4'], ['papayawhip', '#FFEFD5'], ['seagreen', '#2E8B57'], ['goldenrod', '#DAA520'], ['slategray', '#708090'], ['peachpuff', '#FFDAB9']].map(([n, c]) => `<div class="card" style="padding:0;overflow:hidden"><div style="height:130px;background:${c}"></div><div style="padding:14px 16px"><b class="mono" style="font-size:18px">${n}</b><div class="mono" style="color:#6B6358;font-size:14px">${c}</div></div></div>`).join('')}</div>`) };
S['building-color-scales-for-design-systems'] = { alt: 'Design system color scale with eleven steps from 50 to 950', html: frame('Color scale 50–950', `<div class="row" style="gap:8px;align-items:stretch">${[[97, 50], [93, 100], [86, 200], [76, 300], [64, 400], [52, 500], [43, 600], [35, 700], [27, 800], [20, 900], [12, 950]].map(([l, s]) => `<div style="width:86px;height:400px;border-radius:16px;background:hsl(36 ${l > 85 ? 34 : 40}% ${l}%);display:flex;align-items:flex-end;justify-content:center;padding-bottom:14px;font:800 16px ui-monospace,Menlo,monospace;color:${l > 55 ? '#141414' : '#fff'}">${s}</div>`).join('')}</div>`) };
S['mesh-gradients-in-css-guide'] = { alt: 'Soft multi-color mesh gradient background made with layered CSS radial gradients', html: frame('Mesh gradient', `<div style="width:1000px;height:430px;border-radius:28px;background-color:#f3ecdf;background-image:radial-gradient(at 18% 22%,#e0a96d 0,transparent 55%),radial-gradient(at 82% 30%,#c9b28a 0,transparent 55%),radial-gradient(at 30% 85%,#8a6d3b 0,transparent 55%),radial-gradient(at 75% 85%,#f6d5b5 0,transparent 55%),radial-gradient(at 50% 50%,#d98c5f 0,transparent 45%);box-shadow:0 14px 34px rgba(0,0,0,.12)"></div>`) };

// ---------- css ----------
S['css-gradients-linear-radial-conic-guide'] = { alt: 'Linear, radial and conic CSS gradients shown side by side', html: frame('CSS gradients', [['linear-gradient', 'linear-gradient(135deg,#e8dcc4,#8a6d3b 60%,#141414)'], ['radial-gradient', 'radial-gradient(circle at 35% 35%,#f6d5b5,#c8a97e 40%,#3b2f2a)'], ['conic-gradient', 'conic-gradient(#141414 0 25%,#8a6d3b 0 55%,#e0a96d 0 80%,#e8dcc4 0)']].map(([n, g]) => `<div class="col" style="align-items:center"><div style="width:300px;height:300px;border-radius:${n[0] === 'c' ? '50%' : '24px'};background:${g};box-shadow:0 14px 30px rgba(0,0,0,.12)"></div><span class="mono" style="font-weight:700;font-size:18px">${n}()</span></div>`).join('')) };
S['css-box-shadow-guide-realistic-shadows'] = { alt: 'Three cards with layered CSS box shadows at increasing elevation levels', html: frame('Box shadow', [1, 2, 3].map(l => `<div style="width:280px;height:300px;border-radius:22px;background:#fff;box-shadow:${[1, 2, 4, 8, 16].slice(0, l + 2).map(k => `0 ${k * l * .6}px ${k * l * 1.2}px rgba(60,40,10,${.05 + l * .01})`).join(',')};padding:28px" class="col"><span class="cap">Level ${l}</span>${lines(4)}</div>`).join(''), { bg: '#F3ECDF' }) };
S['border-radius-guide-rounded-corners'] = { alt: 'CSS border-radius shapes from square and rounded corners to pill, circle and blob', html: frame('Border radius', [['0', '0'], ['24px', '24px'], ['999px', '999px'], ['50%', '50%'], ['blob', '60% 40% 30% 70% / 60% 30% 70% 40%']].map(([n, r], i) => `<div class="col" style="align-items:center"><div style="width:${i === 2 ? 220 : 170}px;height:${i === 2 ? 90 : 170}px;margin:${i === 2 ? 40 : 0}px 0;border-radius:${r};background:${['#141414', '#8A6D3B', '#C8A97E', '#E0A96D', '#3B2F2A'][i]}"></div><span class="mono" style="font-weight:700">${n}</span></div>`).join('')) };
S['glassmorphism-backdrop-filter-guide'] = { alt: 'Frosted glass card over colorful shapes using CSS backdrop-filter blur', html: frame('Glassmorphism', `<div style="position:relative;width:900px;height:430px"><div style="position:absolute;left:120px;top:20px;width:260px;height:260px;border-radius:50%;background:#e0a96d"></div><div style="position:absolute;right:120px;bottom:0;width:300px;height:300px;border-radius:50%;background:#3b2f2a"></div><div style="position:absolute;right:300px;top:30px;width:180px;height:180px;border-radius:50%;background:#c9b28a"></div><div style="position:absolute;left:220px;top:90px;width:460px;height:260px;border-radius:28px;background:rgba(255,255,255,.25);backdrop-filter:blur(18px) saturate(160%);border:1px solid rgba(255,255,255,.5);box-shadow:0 8px 32px rgba(0,0,0,.12);padding:34px" class="col"><b style="font-size:32px">Frosted glass</b><span class="mono" style="font-size:18px">backdrop-filter: blur(18px)</span>${lines(3, [80, 60, 70], 'rgba(255,255,255,.7)')}</div></div>`, { bg: 'linear-gradient(135deg,#f3ecdf,#d6c3a0)' }) };
S['css-text-shadow-effects-guide'] = { alt: 'CSS text-shadow effects showing neon glow text and retro 3D text', html: frame('Text shadow', `<div style="width:500px;height:380px;border-radius:24px;background:#141414;display:grid;place-items:center"><span style="font-size:110px;font-weight:800;color:#fff;text-shadow:0 0 6px #fff,0 0 14px #e0a96d,0 0 28px #e0a96d,0 0 56px #e0a96d">Neon</span></div><div style="width:500px;height:380px;border-radius:24px;background:#FAF7F2;display:grid;place-items:center;box-shadow:0 14px 34px rgba(0,0,0,.08)"><span style="font-size:110px;font-weight:800;color:#141414;text-shadow:${[1, 2, 3, 4, 5, 6, 7, 8].map(k => `${k}px ${k}px 0 #C8A97E`).join(',')}">Retro</span></div>`) };
S['css-easing-cubic-bezier-explained'] = { alt: 'Cubic-bezier easing curve graph for CSS animation timing', html: frame('Easing curve', `<div class="card" style="padding:20px"><svg width="400" height="400" viewBox="0 0 400 400"><rect x="40" y="40" width="320" height="320" fill="none" stroke="#E8DCC4" stroke-width="3"/><path d="M40 360 L360 40" stroke="#D6C3A0" stroke-width="3" stroke-dasharray="8 8"/><path d="M40 360 L91 40 M360 40 L136 40" stroke="#8A6D3B" stroke-width="3"/><path d="M40 360 C91 40 136 40 360 40" fill="none" stroke="#141414" stroke-width="7"/><circle cx="91" cy="40" r="12" fill="#141414"/><circle cx="136" cy="40" r="12" fill="#141414"/></svg></div><div class="col" style="gap:30px"><span class="mono" style="font-size:24px;font-weight:700">cubic-bezier(.16, 1, .3, 1)</span>${['ease-out-expo', 'linear'].map((n, j) => `<div><span class="cap">${n}</span><div style="position:relative;width:440px;height:46px;border-radius:99px;background:#fff;margin-top:8px">${[0, .1, .2, .3, .4, .6, .8, 1].map(t => { const p = j ? t : 1 - Math.pow(1 - t, 4); return `<i style="position:absolute;top:8px;left:${8 + p * 394}px;width:30px;height:30px;border-radius:50%;background:${j ? '#C8A97E' : '#141414'};opacity:${.25 + t * .75}"></i>`; }).join('')}</div></div>`).join('')}</div>`) };
S['css-grid-layout-guide'] = { alt: 'CSS Grid page layout with header, sidebar, main content and footer areas', html: frame('CSS Grid', `<div class="card" style="width:900px;height:430px;display:grid;grid-template-columns:220px 1fr 1fr;grid-template-rows:70px 1fr 1fr 60px;gap:14px;padding:18px">${[['header', '1/-1', '', '#141414'], ['sidebar', '', '2/4', '#8A6D3B'], ['main', '2/4', '', '#C8A97E'], ['card', '', '', '#E8DCC4'], ['card', '', '', '#E8DCC4'], ['footer', '1/-1', '', '#3B2F2A']].map(([n, c, r, bg]) => `<div style="grid-column:${c || 'auto'};grid-row:${r || 'auto'};background:${bg};border-radius:12px;display:grid;place-items:center;font:700 18px ui-monospace,Menlo,monospace;color:${bg === '#E8DCC4' || bg === '#C8A97E' ? '#141414' : '#fff'}">${n}</div>`).join('')}</div>`) };
S['flexbox-alignment-explained'] = { alt: 'Flexbox justify-content values flex-start, center and space-between compared', html: frame('Flexbox', `<div class="col" style="gap:20px;width:900px">${['flex-start', 'center', 'space-between'].map(j => `<div><span class="mono" style="font-weight:700;font-size:18px">justify-content: ${j}</span><div style="display:flex;justify-content:${j};gap:14px;background:#fff;border-radius:16px;padding:14px;margin-top:8px">${['#141414', '#8A6D3B', '#C8A97E'].map(c => `<div style="width:120px;height:60px;border-radius:10px;background:${c}"></div>`).join('')}</div></div>`).join('')}</div>`) };
S['fluid-typography-with-clamp'] = { alt: 'Fluid typography with CSS clamp scaling heading size from phone to tablet to desktop', html: frame('clamp() fluid type', [[160, 300, 26, '375px'], [260, 330, 38, '768px'], [440, 300, 56, '1440px']].map(([w, h, f, v]) => `<div class="col" style="align-items:center"><div class="card col" style="width:${w}px;height:${h}px;padding:20px;justify-content:center"><b style="font-size:${f}px;line-height:1.05">Fluid heading</b>${lines(3)}</div><span class="mono" style="font-weight:700">${v} → ${f}px</span></div>`).join('')) };
